    /**
     * Method to retrieve the Plant via PlantFetchOneSummary
     * @param 	summary PlantFetchOneSummary 
     * @return 	PlantFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Plant getPlant( PlantFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PlantFetchOneSummary arg cannot be null" );
    	
    	Plant entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Plant
        	// --------------------------------------
        	CompletableFuture<Plant> futureEntity = queryGateway.query(new FindPlantQuery( new LoadPlantFilter( summary.getPlantId() ) ), ResponseTypes.instanceOf(Plant.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Plant with id " + summary.getPlantId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


